/**
 * A browser may see an optimistic outgoing bubble before the poll that reads
 * its persisted counterpart.  The two rows intentionally have different ids,
 * but share the request id generated by the composer.
 */
export type MergeableChatMessage = {
  id: string;
  createdAt: Date | string;
  externalMessageId?: string | null;
  metadata: unknown;
  status: string | null;
};

const OPTIMISTIC_MESSAGE_PREFIX = "m-new-";

export function messageRequestId(metadata: unknown) {
  if (!metadata || typeof metadata !== "object" || Array.isArray(metadata)) {
    return null;
  }

  const value = (metadata as Record<string, unknown>).requestId;
  return typeof value === "string" && value.trim() ? value : null;
}

function deliveryRank(status: string | null) {
  switch (status) {
    case "read": return 9;
    case "delivered": return 8;
    case "sent": return 7;
    case "accepted": return 6;
    case "pending": return 5;
    case "sending": return 4;
    case "queued": return 3;
    case "uncertain": return 2;
    case "failed": return 1;
    case "cancelled": return 0;
    default: return 2;
  }
}

function preference(message: MergeableChatMessage) {
  // A database row must always replace its optimistic counterpart, even when
  // the provider has not confirmed delivery yet.
  const persisted = message.id.startsWith(OPTIMISTIC_MESSAGE_PREFIX) ? 0 : 100;
  return persisted + deliveryRank(message.status) + (message.externalMessageId ? 1 : 0);
}

function timestamp(value: Date | string) {
  const parsed = new Date(value).getTime();
  return Number.isFinite(parsed) ? parsed : 0;
}

function preferredMessage<T extends MergeableChatMessage>(current: T, candidate: T) {
  const currentPreference = preference(current);
  const candidatePreference = preference(candidate);
  if (candidatePreference !== currentPreference) {
    return candidatePreference > currentPreference ? candidate : current;
  }

  // On an equal state, keep the most recent payload. This lets polling update
  // receipt state without reviving a stale message object from local state.
  return timestamp(candidate.createdAt) >= timestamp(current.createdAt) ? candidate : current;
}

/** Merges polling and optimistic state without rendering one request twice. */
export function mergeChatMessages<T extends MergeableChatMessage>(base: T[], incoming: T[]) {
  const byId = new Map<string, T>();
  for (const message of [...base, ...incoming]) {
    // Incoming values are fresher for an identical persisted id.
    byId.set(message.id, message);
  }

  const byRequestId = new Map<string, T>();
  const withoutRequestId: T[] = [];
  for (const message of byId.values()) {
    const requestId = messageRequestId(message.metadata);
    if (!requestId) {
      withoutRequestId.push(message);
      continue;
    }

    const current = byRequestId.get(requestId);
    byRequestId.set(requestId, current ? preferredMessage(current, message) : message);
  }

  return [...withoutRequestId, ...byRequestId.values()].sort(
    (a, b) => timestamp(a.createdAt) - timestamp(b.createdAt) || a.id.localeCompare(b.id),
  );
}
